"""Разметка записей тегами из taxonomy/tags/*.yaml -> tags, record_tags.

    tag.py [--game wol] [--db path]
Совпадение по ru/en/syn_ru/syn_en: слова в нижнем регистре; слово термина >=4 символов — основа
(рус.: snowball-основа, префикс основы текста; англ.: слово + флексия s/es/ed/ing/er/ly), короче — только точно.
Фраза = подряд идущие слова. Родители тега добавляются автоматически (source='parent'). Идемпотентно.
"""
from __future__ import annotations

import argparse
import re
import sys
import time
from pathlib import Path

import common as C

TAGS_DIR = C.ROOT / "taxonomy" / "tags"
TOK = re.compile(r"[\w]+", re.UNICODE)
SUF = ("ing", "es", "ed", "er", "ly", "s", "d")
MIN = 4

DDL = """
CREATE TABLE IF NOT EXISTS tags(id TEXT PRIMARY KEY, ru TEXT, en TEXT, family TEXT, parent TEXT);
CREATE TABLE IF NOT EXISTS record_tags(record_id INTEGER NOT NULL, tag_id TEXT NOT NULL, source TEXT,
  PRIMARY KEY(record_id, tag_id));
CREATE INDEX IF NOT EXISTS ix_rt_tag ON record_tags(tag_id);
"""
_stem_cache: dict[str, str] = {}


def _stem(w):
    s = _stem_cache.get(w)
    if s is None:
        s = _stem_cache[w] = C.stemmer().stemWord(w)
    return s


def term_key(w: str):
    if len(w) < MIN:
        return ("=", w)
    if w.isascii():
        return ("e", w)
    s = _stem(w)
    return ("r", s) if len(s) >= MIN else ("=", w)


def token_keys(t: str) -> set:
    ks = {("=", t)}
    if t.isascii():
        if len(t) >= MIN:
            ks.add(("e", t))
            for suf in SUF:
                if t.endswith(suf) and len(t) - len(suf) >= MIN:
                    b = t[: -len(suf)]
                    ks.add(("e", b)); ks.add(("e", b + "e"))
    elif len(t) >= MIN:
        s = _stem(t)
        for n in range(MIN, len(s) + 1):
            ks.add(("r", s[:n]))
    return ks


def norm_words(s: str) -> list[str]:
    return TOK.findall((s or "").lower().replace("ё", "е"))


def load_tags():
    import yaml
    items = []
    for f in sorted(TAGS_DIR.glob("*.yaml")):
        d = yaml.safe_load(f.read_text(encoding="utf-8"))
        if isinstance(d, dict):
            d = d.get("tags") or next((v for v in d.values() if isinstance(v, list)), [])
        items += [x for x in (d or []) if isinstance(x, dict) and x.get("id")]
    seen = {}
    for x in items:
        seen[str(x["id"])] = x
    return seen


def build_index(tags):
    idx: dict = {}
    for tid, x in tags.items():
        terms = [x.get("ru"), x.get("en"), *(x.get("syn_ru") or []), *(x.get("syn_en") or [])]
        for t in terms:
            ws = norm_words(str(t)) if t else []
            if not ws:
                continue
            keys = tuple(term_key(w) for w in ws)
            idx.setdefault(keys[0], []).append((keys, tid))
    return idx


def match(text_words, idx, cache):
    pos = []
    for w in text_words:
        k = cache.get(w)
        if k is None:
            k = cache[w] = token_keys(w)
        pos.append(k)
    found = set()
    for i, ks in enumerate(pos):
        for k in ks:
            for keys, tid in idx.get(k, ()):
                if tid in found:
                    continue
                if len(keys) == 1 or all(i + j < len(pos) and keys[j] in pos[i + j] for j in range(1, len(keys))):
                    found.add(tid)
    return found


def run(con, game=None, quiet=False):
    t0 = time.time()
    tags = load_tags()
    if not tags:
        if not quiet:
            print(f"[tag] нет словаря: {TAGS_DIR}/*.yaml")
        return None
    con.executescript(DDL)
    con.execute("DELETE FROM tags")
    con.executemany("INSERT INTO tags(id,ru,en,family,parent) VALUES(?,?,?,?,?)",
                    [(i, x.get("ru"), x.get("en"), x.get("family"), x.get("parent") or None) for i, x in tags.items()])
    parent = {i: (x.get("parent") or None) for i, x in tags.items()}
    idx = build_index(tags)
    w, p = ("WHERE g.slug=?", [game]) if game else ("", [])
    ids = [r[0] for r in con.execute(f"SELECT e.id FROM entries e JOIN games g ON g.id=e.game_id {w}", p)]
    con.executemany("DELETE FROM record_tags WHERE record_id=?", [(i,) for i in ids])
    rows = con.execute(f"SELECT e.id,e.title,e.summary,e.body_md,e.tags FROM entries e JOIN games g ON g.id=e.game_id {w}", p).fetchall()
    cache, out, tagged = {}, [], 0
    for r in rows:
        words = norm_words(" . ".join(str(r[c] or "") for c in ("title", "summary", "body_md", "tags")))
        direct = match(words, idx, cache)
        allt = {t: "auto" for t in direct}
        for t in direct:
            q, hop = parent.get(t), 0
            while q and q in tags and hop < 10:
                allt.setdefault(q, "parent"); q = parent.get(q); hop += 1
        if allt:
            tagged += 1
        out += [(r["id"], t, s) for t, s in allt.items()]
    con.executemany("INSERT OR REPLACE INTO record_tags(record_id,tag_id,source) VALUES(?,?,?)", out)
    con.commit()
    dt = time.time() - t0
    if not quiet:
        pct = 100 * tagged / max(1, len(rows))
        print(f"[tag] {game or 'все игры'}: записей {len(rows)}, с >=1 тегом {tagged} ({pct:.1f}%), "
              f"тегов в словаре {len(tags)}, связей {len(out)}, {dt:.1f}s")
    return len(rows), tagged, dt


def main():
    C.utf8_stdout()
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument("--game"); ap.add_argument("--db")
    a = ap.parse_args()
    if a.db:
        C.DB_PATH = Path(a.db)
    con = C.connect()
    run(con, a.game)


if __name__ == "__main__":
    main()
